%[text] # 4 Laboratorinis
%%
%[text] ## 7 variantas
%%
%[text] ## Karolina Jukneviciute EDIf\_25/1
%%
%[text] ## PRIVALOMA

%% 1 a užduotis
[x, y] = meshgrid(-1:0.05:1);
r = sqrt(x.^2 + y.^2);
z = exp(r.^2);

figure; %[output:0b80fcb6]
surf(x, y, z); %[output:0b80fcb6]
colormap('jet');          %[output:0b80fcb6]
shading interp;            %[output:0b80fcb6]
view(30, 30);              %[output:0b80fcb6]

title('Trimatė paviršiaus grafiko užduotis (a)'); %[output:0b80fcb6]
xlabel('X ašis'); %[output:0b80fcb6]
ylabel('Y ašis'); %[output:0b80fcb6]
zlabel('Z ašis'); %[output:0b80fcb6]
grid on; %[output:0b80fcb6]

%% 1 b užduotis
[x, y] = meshgrid(-2:0.05:1);
f = 1 - 2.*x.^2 - 3.*y.^2;

figure; %[output:41758034]
mesh(x, y, f); %[output:41758034]
colormap('parula');      %[output:41758034]
shading interp;            %[output:41758034]
view(45, 30);              %[output:41758034]

title('Trimatė paviršiaus grafiko užduotis (b)'); %[output:41758034]
xlabel('X ašis'); %[output:41758034]
ylabel('Y ašis'); %[output:41758034]
zlabel('F(x,y) ašis'); %[output:41758034]
grid on; %[output:41758034]


%%
%[text] ## Papildoma užduotis

[x, y] = meshgrid(-1:0.1:1);
z = 1 - (x.^2 + y.^2);

rezimai = {'flat', 'faceted', 'interp'};

figure('Name', 'shading savybės', 'Position', [100, 100, 1100, 350]); %[output:05445da9]
for k = 1:3 %[output:group:9b1b1445]
    subplot(1, 3, k); %[output:05445da9]
    surf(x, y, z);
    colormap('jet');
    shading(rezimai{k});
    view(45, 30);
    title(['shading ', rezimai{k}]);
    xlabel('X ašis');
    ylabel('Y ašis');
    zlabel('Z ašis');
    grid on;
end %[output:group:9b1b1445]



